use serde::{Deserialize, Serialize};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub enum Mode { Classic, Double, X20, X40, HighRoller, X80, Whale, X200, X400, X800, X1000, X10000, Degenerate }

#[derive(Clone, Copy, Debug)]
#[allow(dead_code)]
pub struct ModeConfig { pub name: &'static str, pub multiplier: u64, pub min_bet: u64, pub blackjack_num: u64, pub blackjack_den: u64, pub surrender: bool, pub insurance: bool, pub dealer_hits_soft_17: bool, pub level: u32 }

impl Mode { pub fn config(self) -> ModeConfig { match self { Self::Classic => ModeConfig { name: "x1 Classic", multiplier: 1, min_bet: 10, blackjack_num: 3, blackjack_den: 2, surrender: true, insurance: true, dealer_hits_soft_17: false, level: 1 }, Self::Double => ModeConfig { name: "x2 Double", multiplier: 2, min_bet: 50, blackjack_num: 3, blackjack_den: 2, surrender: true, insurance: true, dealer_hits_soft_17: false, level: 2 }, Self::X20 => ModeConfig { name: "x20", multiplier: 20, min_bet: 200, blackjack_num: 3, blackjack_den: 2, surrender: true, insurance: true, dealer_hits_soft_17: false, level: 3 }, Self::X40 => ModeConfig { name: "x40", multiplier: 40, min_bet: 400, blackjack_num: 3, blackjack_den: 2, surrender: true, insurance: true, dealer_hits_soft_17: false, level: 4 }, Self::HighRoller => ModeConfig { name: "x10 High Roller", multiplier: 10, min_bet: 500, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: true, dealer_hits_soft_17: false, level: 5 }, Self::X80 => ModeConfig { name: "x80", multiplier: 80, min_bet: 1000, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: true, dealer_hits_soft_17: false, level: 6 }, Self::Whale => ModeConfig { name: "x100 Whale", multiplier: 100, min_bet: 5_000, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: false, dealer_hits_soft_17: true, level: 10 }, Self::X200 => ModeConfig { name: "x200", multiplier: 200, min_bet: 10_000, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: false, dealer_hits_soft_17: true, level: 12 }, Self::X400 => ModeConfig { name: "x400", multiplier: 400, min_bet: 20_000, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: false, dealer_hits_soft_17: true, level: 15 }, Self::X800 => ModeConfig { name: "x800", multiplier: 800, min_bet: 40_000, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: false, dealer_hits_soft_17: true, level: 20 }, Self::X1000 => ModeConfig { name: "x1000", multiplier: 1000, min_bet: 100_000, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: false, dealer_hits_soft_17: true, level: 25 }, Self::X10000 => ModeConfig { name: "x10000", multiplier: 10000, min_bet: 1_000_000, blackjack_num: 3, blackjack_den: 2, surrender: false, insurance: false, dealer_hits_soft_17: true, level: 50 }, Self::Degenerate => ModeConfig { name: "x1000 Degenerate", multiplier: 1000, min_bet: 50_000, blackjack_num: 6, blackjack_den: 5, surrender: false, insurance: false, dealer_hits_soft_17: true, level: 1 } } } pub fn unlocked(self, level: u32, broken_bank: bool) -> bool { match self { Self::Degenerate => broken_bank, _ => level >= self.config().level } } pub fn next(self) -> Self { match self { Self::Classic => Self::Double, Self::Double => Self::X20, Self::X20 => Self::X40, Self::X40 => Self::HighRoller, Self::HighRoller => Self::X80, Self::X80 => Self::Whale, Self::Whale => Self::X200, Self::X200 => Self::X400, Self::X400 => Self::X800, Self::X800 => Self::X1000, Self::X1000 => Self::X10000, Self::X10000 => Self::Degenerate, Self::Degenerate => Self::Classic } } pub fn previous(self) -> Self { match self { Self::Classic => Self::Degenerate, Self::Double => Self::Classic, Self::X20 => Self::Double, Self::X40 => Self::X20, Self::HighRoller => Self::X40, Self::X80 => Self::HighRoller, Self::Whale => Self::X80, Self::X200 => Self::Whale, Self::X400 => Self::X200, Self::X800 => Self::X400, Self::X1000 => Self::X800, Self::X10000 => Self::X1000, Self::Degenerate => Self::X10000 } } #[allow(dead_code)] pub fn all() -> [Self; 13] { [Self::Classic, Self::Double, Self::X20, Self::X40, Self::HighRoller, Self::X80, Self::Whale, Self::X200, Self::X400, Self::X800, Self::X1000, Self::X10000, Self::Degenerate] } }
